package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ClonePair5168DifferenceFindingTest {

    private final ClonePair5168 subject = new ClonePair5168();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsDisagreeWhenTheSameNaNArrayIsPassedForBothArguments() {
        // method2 short-circuits on reference identity, whereas method1 compares element-wise
        // and NaN is never equal to itself.
        double[] values = {Double.NaN};

        assertFalse(subject.method1(values, values));
        assertTrue(subject.method2(values, values));
    }
}
